// Monta as consultas do Gleap. Uma linha por (marca, consulta). O operador vai no NOME do
// parametro (createdAt%3E = "createdAt >="). Os ":" da data NAO podem ser percent-encoded
// (409 CastError), por isso a URL e montada aqui e nao em "Query Parameters".
const modo = $input.first().json.modo || 'hoje';
const MARCAS = [
  { marca: 'aristocrata', projeto: '6970d219368e0dea0fc91c42' },
  { marca: 'fishermans',  projeto: '696f91650c6a7fc35f38be62' },
];
const sp = new Date(Date.now() - 3 * 3600 * 1000);            // agora em Sao Paulo
const ymd = (d) => d.toISOString().slice(0, 10);
const hojeSP = ymd(sp);
const inicio = new Date(sp); inicio.setUTCDate(inicio.getUTCDate() - (modo === 'noturno' ? 45 : 0));
const desde = ymd(inicio) + 'T03:00:00.000Z';                // 00:00 SP em UTC
const base = 'https://api.gleap.io/v3/tickets?limit=500&createdAt%3E=' + desde;
const out = [];
for (const m of MARCAS) {
  out.push({ json: { marca: m.marca, projeto: m.projeto, tipo: 'lista', rating: null, url: base } });
  if (modo === 'noturno') for (const r of [2, 6, 10])
    out.push({ json: { marca: m.marca, projeto: m.projeto, tipo: 'rating', rating: r, url: base + '&conversationRating=' + r } });
}
return out;

// Reanexa marca/tipo/rating da consulta de origem a cada pagina devolvida.
// Usa o pairedItem que o HTTP Request mantem, entao funciona com qualquer numero de paginas.
const c = $('Monta consultas').item.json;
return { json: Object.assign({}, $input.item.json, { _meta: { marca: c.marca, tipo: c.tipo, rating: c.rating } }) };

// Achata a resposta paginada em uma linha por ticket, com os campos que o painel usa.
// Regras (iguais ao backfill de 12/09 e ao COMMENT de cx_ticket):
//  - escalado = processingTeam OU processingUser preenchido (transferencia real)
//  - motivo = precedencia problema > cancelamento > troca > wismo > pre-venda > outros; sem tag -> null
//  - kai-pode-atender e roteamento, nao motivo
const PREC = ['problema', 'cancelamento', 'troca', 'wismo', 'pre-venda', 'outros'];
const id = (x) => (x && typeof x === 'object') ? (x.id || x._id || null) : (x || null);
const out = [];
for (const item of $input.all()) {
  const meta = item.json._meta || {};
  const tickets = item.json.tickets || [];
  for (const t of tickets) {
    const tags = Array.isArray(t.tags) ? t.tags : [];
    const criado = new Date(t.createdAt);
    const diaSP = new Date(criado.getTime() - 3 * 3600 * 1000).toISOString().slice(0, 10);
    out.push({ json: {
      ticket_id: t.id, marca: meta.marca, canal: (t.channel && t.channel.type) || null, dia: diaSP,
      criado_em: t.createdAt, status: t.status || null, tipo: t.type || null, tags,
      motivo: PREC.find((m) => tags.includes(m)) || null,
      kai_pode_atender: tags.includes('kai-pode-atender'), csat_enviado: tags.includes('csat enviado'),
      rating: meta.tipo === 'rating' ? meta.rating : null,
      escalado: !!(t.processingTeam || t.processingUser),
      processing_team: id(t.processingTeam), processing_user: id(t.processingUser),
      has_agent_reply: typeof t.hasAgentReply === 'boolean' ? t.hasAgentReply : null,
      human_handoff_em: (t.humanHandoff && t.humanHandoff.at) || null,
      spam: !!t.isSpam, teste: !!t.isTestRun, so_rating: meta.tipo === 'rating',
    } });
  }
}
return out;

// Um INSERT ... ON CONFLICT por lote de 400 linhas. Linhas de consulta "rating" so
// atualizam a nota (COALESCE mantem a que ja existe). NULL nunca vira 0.
const q = (v) => v === null || v === undefined ? 'NULL'
  : typeof v === 'boolean' ? (v ? 'true' : 'false')
  : typeof v === 'number' ? String(v)
  : Array.isArray(v) ? (v.length ? 'ARRAY[' + v.map((x) => "'" + String(x).replace(/'/g, "''") + "'").join(',') + ']::text[]' : "'{}'::text[]")
  : "'" + String(v).replace(/'/g, "''") + "'";
const linhas = $input.all().map((i) => i.json);
const lista = linhas.filter((l) => !l.so_rating);
const notas = linhas.filter((l) => l.so_rating);
const cols = 'ticket_id,marca,canal,dia,criado_em,status,tipo,tags,motivo,kai_pode_atender,csat_enviado,rating,escalado,processing_team,processing_user,has_agent_reply,human_handoff_em,spam,teste';
const out = [];
for (let i = 0; i < lista.length; i += 400) {
  const vals = lista.slice(i, i + 400).map((l) => '(' + [l.ticket_id, l.marca, l.canal, l.dia, l.criado_em, l.status, l.tipo, l.tags, l.motivo,
    l.kai_pode_atender, l.csat_enviado, l.rating, l.escalado, l.processing_team, l.processing_user, l.has_agent_reply, l.human_handoff_em, l.spam, l.teste].map(q).join(',') + ')').join(',');
  out.push({ json: { sql: `INSERT INTO cx_ticket (${cols}) VALUES ${vals}
    ON CONFLICT (ticket_id) DO UPDATE SET status=EXCLUDED.status, tags=EXCLUDED.tags, motivo=EXCLUDED.motivo,
      kai_pode_atender=EXCLUDED.kai_pode_atender, csat_enviado=EXCLUDED.csat_enviado, escalado=EXCLUDED.escalado,
      processing_team=EXCLUDED.processing_team, processing_user=EXCLUDED.processing_user, has_agent_reply=EXCLUDED.has_agent_reply,
      human_handoff_em=EXCLUDED.human_handoff_em, spam=EXCLUDED.spam, teste=EXCLUDED.teste, atualizado_em=now()`, n: Math.min(400, lista.length - i), tipo: 'lista' } });
}
for (let i = 0; i < notas.length; i += 400) {
  const lote = notas.slice(i, i + 400);
  const vals = lote.map((l) => '(' + [l.ticket_id, l.marca, l.canal, l.dia, l.criado_em, l.status, l.tipo, l.tags, l.motivo,
    l.kai_pode_atender, l.csat_enviado, l.rating, l.escalado, l.processing_team, l.processing_user, l.has_agent_reply, l.human_handoff_em, l.spam, l.teste].map(q).join(',') + ')').join(',');
  // ticket avaliado que ainda nao esta na tabela (fora da janela da lista) entra pela consulta de nota
  out.push({ json: { sql: `INSERT INTO cx_ticket (${cols}) VALUES ${vals}
    ON CONFLICT (ticket_id) DO UPDATE SET rating=EXCLUDED.rating, atualizado_em=now()`, n: lote.length, tipo: 'rating' } });
}
if (!out.length) out.push({ json: { sql: 'SELECT 0 AS nada', n: 0, tipo: 'vazio' } });
return out;
